static int osif_usb_read(struct i2c_adapter *adapter, int cmd,
			 int value, int index, void *data, int len)
{
	struct osif_priv *priv = adapter->algo_data;
	int pipe;
	u8 request_type;

	if (len) {
		pipe = usb_rcvctrlpipe(priv->usb_dev, 0);
		request_type = USB_TYPE_VENDOR | USB_RECIP_INTERFACE | USB_DIR_IN;
	} else {
		pipe = usb_sndctrlpipe(priv->usb_dev, 0);
		request_type = USB_TYPE_VENDOR | USB_RECIP_INTERFACE;
	}

	return usb_control_msg(priv->usb_dev, pipe,
			       cmd, request_type, value, index, data, len, 2000);
}

